  * { box-sizing: border-box; }

  body {
     margin: 0;

    padding: 32px 16px;
    font-family: Georgia, "Times New Roman", serif;
    background: #fffdf7;
    display: flex;
    justify-content: center;
}

.bai-viet {
    width: min(860px, 100%);
}

.bai-viet h1 {
    margin: 0 0 4px;
    color: #E65100;
    font-size: 30px;
    line-height: 1.2;
}

.bai-viet h1 span {
    display: block;
    font-size: 0.6em;
    font-weight: 400;
}

.cot-bai {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 24px;
    margin-top: 16px;
    align-items: start;
}

.cot-bai p {
    margin: 0 0 14px;
    line-height: 1.8;
    text-align: justify;
}

.cot-bai p:first-of-type::first-letter {
    float: left;
    font-size: 3rem;
    line-height: 0.85;
    color: #E65100;
    font-weight: 700;
    padding: 0.1rem 0.35rem 0 0;
}

.cot-bai img {
    width: 100%;
    border-radius: 8px;
    display: block;
}

.hop-phu {
    margin-top: 20px;
    border: 2px solid #2E7D32;
    border-radius: 8px;
    padding: 16px 20px;
    background: #f4fbf4;
}

.hop-phu h2 {
    margin: 0 0 10px;
    color: #2E7D32;
    font-style: italic;
    font-size: 17px;
}

.hop-phu ul {
    margin: 0;
    padding-left: 20px;
    columns: 2;
    column-gap: 32px;
    line-height: 1.9;
}

  @media (max-width: 640px) {
      .cot-bai { grid-template-columns: 1fr; }
      .hop-phu ul { columns: 1; }
  }
